INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q4870907', 'Battle of Dorestad', 'The Battle of Dorestad was a 7th-century battle between the Franks and the Frisians. The battle took place around 695 by the capital city of the Frisians close to the Rhine.', 695, NULL, NULL, NULL, NULL, NULL, 'year', '695', 43, 'https://en.wikipedia.org/wiki/Battle_of_Dorestad'),
  ('Q2038283', 'Battle of the Boarn', 'The Battle of the Boarn (West Frisian: Slach oan de Boarn; Dutch: Slag aan de Boorne) or Battle by Jirnsum was an 8th century battle between the Franks and the Frisians near the mouth of the river Boarn in what is now Jirnsum in the Dutch province of Friesland.', 734, NULL, NULL, NULL, NULL, NULL, 'year', '734', 52, 'https://en.wikipedia.org/wiki/Battle_of_the_Boarn'),
  ('Q2119849', 'Battle of Vlaardingen', 'The (First) Battle of Vlaardingen was fought on 29 July 1018 between troops of the Holy Roman Empire and West Frisia (which would later become known as the County of Holland). As a result of a trade dispute, Emperor Henry II sent an army towards West Frisia to subdue the rebellious Count Dirk III. However, the Imperial army was decisively defeated and fled in panic.', 1018, 7, 29, NULL, NULL, NULL, 'day', '29 July 1018', 48, 'https://en.wikipedia.org/wiki/Battle_of_Vlaardingen'),
  ('Q2669581', 'Loon War', 'The Loon War (Dutch: Loonse Oorlog) was a war of succession over the County of Holland (and its dependency Zeeland) from 1203 until 1206, brought on by the death of count Dirk VII. The war was waged between Dirk''s brother William of Frisia, and Dirk''s daughter Ada who had quickly married count Louis II of Loon.', 1203, NULL, NULL, 1206, NULL, NULL, 'year', '1203–1206', 43, 'https://en.wikipedia.org/wiki/Loon_War'),
  ('Q2431866', 'Battle of Zierikzee', 'The battle of Zierikzee was a naval battle between a Flemish fleet and an allied Franco-Hollandic fleet which took place on 10 and 11 August 1304. The battle, fought near the town of Zierikzee, ended in a Franco-Dutch victory.', 1304, 8, 10, 1304, 8, 11, 'day', '10 August 1304 – 11 August 1304', 43, 'https://en.wikipedia.org/wiki/Battle_of_Zierikzee'),
  ('Q2231652', 'Relief of Goes', 'In August 1572, during the course of the Eighty Years'' War, the city of Goes, in the Spanish Netherlands, was besieged by Dutch forces, including several English volunteers. This was a menace to the safety of the nearby city of Middelburg, also under siege.', 1572, 10, 20, 1572, 10, 20, 'day', '20 October 1572', 43, 'https://en.wikipedia.org/wiki/Relief_of_Goes'),
  ('Q2350145', 'Siege of Alkmaar', 'The siege of Alkmaar (1573) was a turning point in the Eighty Years'' War. The burghers of the Dutch city of Alkmaar held off the Spanish (who had set up their camp in Oudorp) between 21 August and 8 October 1573, with boiling tar and burning branches from their renewed city walls.', 1573, 10, 8, 1573, 10, 8, 'day', '8 October 1573', 43, 'https://en.wikipedia.org/wiki/Siege_of_Alkmaar'),
  ('Q2386251', 'Battle on the Zuiderzee', 'The Battle on the Zuiderzee (October 11, 1573) was a naval battle during the Eighty Years'' War in which a Dutch fleet triumphed over a larger and better-equipped Spanish fleet on the Zuiderzee.', 1573, 10, 11, NULL, NULL, NULL, 'day', '11 October 1573', 43, 'https://en.wikipedia.org/wiki/Battle_on_the_Zuiderzee'),
  ('Q694619', 'Siege of Leiden', 'The siege of Leiden occurred during the Eighty Years'' War in 1573 and 1574, when the Spanish under Francisco de Valdez attempted to capture the rebellious city of Leiden, South Holland, the Netherlands. The siege failed when the city was successfully relieved in October 1574.', 1574, 10, 3, 1574, 10, 3, 'day', '3 October 1574', 48, 'https://en.wikipedia.org/wiki/Siege_of_Leiden'),
  ('Q744588', 'Battle of Reimerswaal', 'The Battle of the Scheldt also known as the Battle of Walcheren (known in Dutch as Slag bij Reimerswaal) was a naval battle that took place on 29 January 1574 during the Eighty Years'' War. The battle was fought between a Dutch rebel Sea Beggar fleet (which included English and Scottish volunteers) under Lodewijk van Boisot and a Spanish fleet under Julián Romero.', 1574, 1, 29, NULL, NULL, NULL, 'day', '29 January 1574', 43, 'https://en.wikipedia.org/wiki/Battle_of_the_Scheldt_(1574)'),
  ('Q4870969', 'Battle of Empel', 'The Miracle of Empel (Milagro de Empel in Spanish) was a Spanish victory on December 8, 1585, near Empel, in the Netherlands during the Eighty Years'' War. A Dutch force under Philip of Hohenlohe-Neuenstein had trapped several thousand Spanish soldiers of the Army of Flanders under Francisco Arias de Bobadilla on an island between the Meuse and Waal rivers by breaching dikes and using naval patrols.', 1585, 12, 7, 1585, 12, 8, 'day', '7 December 1585 – 8 December 1585', 47, 'https://en.wikipedia.org/wiki/Battle_of_Empel'),
  ('Q2890458', 'Battle of Zutphen', 'The Battle of Zutphen was fought on 22 September 1586, near the village of Warnsveld and the town of Zutphen, the Netherlands, during the Eighty Years'' War and the Anglo-Spanish War (1585–1604). It was fought between the forces of the United Provinces of the Netherlands, aided by the English, against the Spanish.', 1586, 9, 22, NULL, NULL, NULL, 'day', '22 September 1586', 48, 'https://en.wikipedia.org/wiki/Battle_of_Zutphen'),
  ('Q2114424', 'Battle of Sluis', 'The Battle of Sluis was a naval battle during the Eighty Years'' War in which a Spanish squadron commanded by the Italian captain Federico Spinola tried to break through a blockade of Sluis by Dutch ships under the command of Joos de Moor. After about two hours of fighting the heavily damaged Spanish ships returned to Sluis.', 1603, 5, 26, NULL, NULL, NULL, 'day', '26 May 1603', 45, 'https://en.wikipedia.org/wiki/Battle_of_Sluis_(1603)'),
  ('Q1838038', 'Siege of Bergen op Zoom', 'The siege of Bergen op Zoom (1622) was a siege during the Eighty Years'' War that took place from 18 July to 2 October 1622. The Spanish general Ambrosio Spinola laid siege to the Dutch city of Bergen op Zoom.', 1622, NULL, NULL, 1622, 10, 2, 'year', '1622', 47, 'https://en.wikipedia.org/wiki/Siege_of_Bergen_op_Zoom_(1622)'),
  ('Q371252', 'Siege of Groenlo', 'The siege of Grol in 1627 was a battle between the Army of the Dutch Republic, commanded by Frederick Henry, Prince of Orange, and the Spanish-controlled fortified city of Grol (now known as Groenlo), during the Eighty Years War and the Anglo–Spanish War in 1627. The Spanish Army, led by Hendrik van den Bergh, came to relieve Grol but too late.', 1627, 7, 20, 1627, 8, 19, 'day', '20 July 1627 – 19 August 1627', 43, 'https://en.wikipedia.org/wiki/Siege_of_Groenlo_(1627)'),
  ('Q575737', 'Battle of Scheveningen', 'The Battle of Scheveningen was the final naval battle of the First Anglo-Dutch War. It took place on 31 July 1653 between the fleets of the Commonwealth of England and the Dutch Republic.', 1653, 8, 8, 1653, 8, 10, 'day', '8 August 1653 – 10 August 1653', 50, 'https://en.wikipedia.org/wiki/Battle_of_Scheveningen'),
  ('Q1807803', 'explosion of the powder magazine in Delft', 'Delft (Dutch pronunciation: [ˈdɛl(ə)ft] ) is a city and municipality in the province of South Holland, Netherlands. It is located between Rotterdam, to the southeast, and The Hague, to the northwest.', 1654, 10, 12, NULL, NULL, NULL, 'day', '12 October 1654', 47, 'https://en.wikipedia.org/wiki/Delft_Explosion'),
  ('Q2383784', 'Treaty of The Hague', 'The Treaty of The Hague (also known as the Treaty of Den Haag) was signed on 6 August 1661 between representatives of the Dutch Republic and Portugal. Based on the terms of the treaty, the Dutch Republic recognized Portuguese sovereignty over New Holland (Dutch Brazil) in exchange for an indemnity of 4 million reis, conversion from 2 million caroli guilders, over the span of 16 years.', 1661, 8, 6, NULL, NULL, NULL, 'day', '6 August 1661', 52, 'https://en.wikipedia.org/wiki/Treaty_of_The_Hague_(1661)'),
  ('Q681814', 'Siege of Groningen', 'The siege of Groningen was a battle that took place in 1672 during the Franco-Dutch War. It was a Dutch victory that ended all hope of the Bishop of Münster to push deeper into the Netherlands.', 1672, 7, 9, 1672, 8, 17, 'day', '9 July 1672 – 17 August 1672', 51, 'https://en.wikipedia.org/wiki/Siege_of_Groningen_(1672)'),
  ('Q540121', 'Siege of Maastricht', 'The Siege of Maastricht, 13 to 30 June 1673, took place during the Franco-Dutch War, when a French army captured the strategic Dutch fortress of Maastricht on the Meuse river. Siege operations were conducted by Vauban, and is thought to be the first use of a technique known as the "siege parallel", a concept that remained in use until the mid-20th century.', 1673, NULL, NULL, 1673, 6, 26, 'year', '1673', 55, 'https://en.wikipedia.org/wiki/Siege_of_Maastricht_(1673)'),
  ('Q2119018', 'Treaty of The Hague', 'The 1698 Treaty of The Hague, also known as the 1698 Treaty of Den Haag or First Partition Treaty was one of two attempts by France, Great Britain, and the Dutch Republic to achieve a diplomatic solution to the issues that led to the 1701–1714 War of the Spanish Succession. The death of Charles II had been anticipated from his succession in 1665, but by 1697 appeared clearly imminent.', 1698, 10, 11, NULL, NULL, NULL, 'day', '11 October 1698', 48, 'https://en.wikipedia.org/wiki/Treaty_of_The_Hague_(1698)'),
  ('Q638845', 'Treaty of The Hague', 'The Treaty of Den Haag, or Treaty of The Hague, was signed on 7 September 1701 between England, the Holy Roman Emperor Leopold I, and the United Provinces. It reconstituted the 1689 anti-French Grand Alliance in response to the issues that resulted in the War of the Spanish Succession.', 1701, 9, 7, NULL, NULL, NULL, 'day', '7 September 1701', 48, 'https://en.wikipedia.org/wiki/Treaty_of_The_Hague_(1701)'),
  ('Q154674', 'Peace of Utrecht', 'The Peace of Utrecht was a series of peace treaties signed by the belligerents in the War of the Spanish Succession, in the Dutch city of Utrecht between April 1713 and February 1715. The war involved three contenders for the vacant throne of Spain, and had involved much of Europe for over a decade.', 1713, NULL, NULL, NULL, NULL, NULL, 'year', '1713', 79, 'https://en.wikipedia.org/wiki/Peace_of_Utrecht'),
  ('Q1893619', 'Treaty of The Hague', 'The Treaty of The Hague was signed on 17 February 1720 between Spain and the Quadruple Alliance, established by the 1718 Treaty of London. Its members included Britain, France, the Dutch Republic and Austria.', 1720, 2, 17, NULL, NULL, NULL, 'day', '17 February 1720', 52, 'https://en.wikipedia.org/wiki/Treaty_of_The_Hague_(1720)'),
  ('Q1835856', 'Siege of Bergen op Zoom', 'The siege of Bergen op Zoom took place during the Austrian War of Succession, when a French army, under the command of Count Löwendal and the overall direction of Marshal Maurice de Saxe, laid siege and captured the strategic Dutch border fortress of Bergen op Zoom on the border of Brabant and Zeeland in 1747. The fortress was defended by Dutch, Austrians, British, Hanoverians and Hessians that supported the Pragmatic Sanction.', 1747, 7, NULL, 1747, 9, NULL, 'month', 'July 1747 – September 1747', 47, 'https://en.wikipedia.org/wiki/Siege_of_Bergen_op_Zoom_(1747)'),
  ('Q289609', 'Siege of Maastricht', 'The siege of Maastricht was a campaign during the War of the Austrian Succession which took place in April–May 1748.', 1748, 4, 15, 1748, 5, 7, 'day', '15 April 1748 – 7 May 1748', 47, 'https://en.wikipedia.org/wiki/Siege_of_Maastricht_(1748)'),
  ('Q183447', 'Capture of the Dutch fleet at Den Helder', 'The capture of the Dutch fleet at Den Helder on the night of 23 January 1795 presents a rare occurrence of an interaction between warships and cavalry, in which a French Revolutionary Hussar regiment came close to a Dutch fleet frozen at anchor in the Nieuwediep, just east of the town of Den Helder. After some of the Hussars had approached across the frozen Nieuwediep, the French cavalry negotiated that all 14 Dutch warships would remain at anchor.', 1795, 1, 23, NULL, NULL, NULL, 'day', '23 January 1795', 50, 'https://en.wikipedia.org/wiki/Capture_of_the_Dutch_fleet_at_Den_Helder'),
  ('Q370376', 'Battle of Castricum', 'The Battle of Castricum (October 6, 1799) saw a Franco-Batavian force defeat an Anglo-Russian force near Castricum, Netherlands, within the Anglo-Russian invasion of Holland. The battle was fought during the War of the Second Coalition against Revolutionary France between French–Batavian forces under the command of generals Guillaume Brune (commander-in-chief) and Herman Willem Daendels and British–Russian forces under the command of the Duke of York (commander-in-chief) and General Ivan Essen.', 1799, 10, 6, NULL, NULL, NULL, 'day', '6 October 1799', 50, 'https://en.wikipedia.org/wiki/Battle_of_Castricum'),
  ('Q793448', 'Battle of Bergen', 'The Battle of Bergen was fought on 19 September 1799 and resulted in a Franco-Batavian victory, as Generals Guillaume Brune and Herman Willem Daendels (Brune commanded both his own French and Daendels'' Batavians) defeated the Anglo-Russian forces that had landed in North Holland under the Duke of York as supreme commander and Lieutenant General Johann Hermann von Fersen. Due to a lack of cooperation between the British and Russians they were both defeated in detail, with von Fersen being captured by French troops.', 1799, 9, 19, NULL, NULL, NULL, 'day', '19 September 1799', 45, 'https://en.wikipedia.org/wiki/Battle_of_Bergen_(1799)'),
  ('Q4141642', 'Anglo-Russian invasion of Holland', 'The Anglo-Russian invasion of Holland (or Anglo-Russian expedition to Holland, or Helder Expedition) was a military campaign from 27 August to 19 November 1799 during the War of the Second Coalition, in which an expeditionary force of British and Russian troops invaded the North Holland peninsula in the Batavian Republic. The campaign had two strategic objectives: to neutralize the Batavian fleet and to promote an uprising by followers of the former stadtholder William V against the Batavian government.', 1799, 8, 27, 1799, 11, 19, 'day', '27 August 1799 – 19 November 1799', 50, 'https://en.wikipedia.org/wiki/Anglo-Russian_invasion_of_Holland'),
  ('Q1080899', 'Walcheren Campaign', 'The Walcheren Campaign (Dutch pronunciation: [ˈʋɑlxərə(n)]) was an unsuccessful British expedition to the Kingdom of Holland in 1809 intended to open another front in the Austrian Empire''s struggle with France during the War of the Fifth Coalition. John Pitt, 2nd Earl of Chatham, the commander of the expedition, was ordered to capture the towns of Flushing (Vlissingen) and Antwerp and thus enable British ships to safely traverse the Scheldt River.', 1809, 12, 9, NULL, NULL, NULL, 'day', '9 December 1809', 55, 'https://en.wikipedia.org/wiki/Walcheren_Campaign'),
  ('Q751398', 'International Opium Convention', 'The First International Opium Convention (also called 1912 Opium Convention or Hague Opium Convention) is a former international treaty signed at The Hague in 1912. The conference were an international effort by states to regulate the trade of opium and suppress illicit opium consumption.', 1912, 1, 23, NULL, NULL, NULL, 'day', '23 January 1912', 65, 'https://en.wikipedia.org/wiki/First_International_Opium_Convention'),
  ('Q2477486', 'Battle off Texel', 'The Battle off Texel, also known as the Action off Texel or the Action of 17 October 1914, was a naval battle off the coast of the Dutch island of Texel during the First World War. A British squadron, comprising one light cruiser and four destroyers on a routine patrol, encountered the German 7th Half Flotilla of torpedo boats which was en route to the British coast to lay mines.', 1914, 10, 17, NULL, NULL, NULL, 'day', '17 October 1914', 45, 'https://en.wikipedia.org/wiki/Battle_off_Texel'),
  ('Q2636209', 'Action of 22 September 1914', 'The Action of 22 September 1914 was an attack by the German U-boat U-9 that took place during the First World War. Three obsolete Royal Navy cruisers of the 7th Cruiser Squadron manned mainly by Royal Naval Reserve part-timers and sometimes referred to as the Live Bait Squadron, were sunk by U-9 while patrolling the southern North Sea.', 1914, 9, 22, NULL, NULL, NULL, 'day', '22 September 1914', 51, 'https://en.wikipedia.org/wiki/Action_of_22_September_1914'),
  ('Q8698', 'Great Depression', 'The Great Depression was a severe global economic downturn from 1929 to 1939. The period was marked by high rates of unemployment and poverty, drastic reductions in industrial production and international trade, and widespread bank and business failures around the world.', 1929, 10, 29, 1941, NULL, NULL, 'day', '29 October 1929 – 1941', 93, 'https://en.wikipedia.org/wiki/Great_Depression'),
  ('Q714979', 'Battle of the Afsluitdijk', 'The Battle of the Afsluitdijk of 12–14 May 1940 was an unsuccessful attempt by German Wehrmacht forces to seize the Afsluitdijk during the invasion of the Netherlands. German invasion plans called for a simultaneous attack on Vesting Holland from multiple directions, expecting to capture the country''s capital and most important region in a day''s time.', 1940, 5, 12, 1940, 5, 14, 'day', '12 May 1940 – 14 May 1940', 50, 'https://en.wikipedia.org/wiki/Battle_of_the_Afsluitdijk'),
  ('Q716750', 'Battle of Maastricht', 'The Battle of Maastricht was one of the first battles that took place during the German Campaign on the Western Front during World War II. Maastricht was a key city in order to capture the Belgian Fort Eben-Emael and split the allied armies in half. The German goal of the operation was to take the main bridges over the river Maas intact, to have an easier road to central Belgium.', 1940, 5, 10, NULL, NULL, NULL, 'day', '10 May 1940', 50, 'https://en.wikipedia.org/wiki/Battle_of_Maastricht'),
  ('Q1891631', 'Battle for The Hague', 'The Battle for The Hague (Dutch: Slag om Den Haag) took place on 10 May 1940 during the Battle of the Netherlands. German Fallschirmjäger units were dropped in and around The Hague to capture Dutch airfields and the city itself.', 1940, 5, 10, NULL, NULL, NULL, 'day', '10 May 1940', 56, 'https://en.wikipedia.org/wiki/Battle_of_the_Hague_(1940)'),
  ('Q2649081', 'German invasion of the Netherlands', 'The German invasion of the Netherlands, otherwise known as the Battle of the Netherlands, was a military campaign, part of Case Yellow (German: Fall Gelb), the Nazi German invasion of the Low Countries (Belgium, Luxembourg, and the Netherlands) and France during World War II. The battle lasted from 10 May 1940 until the surrender of the main Dutch forces on 14 May. Dutch troops under French command in the far southwestern province of Zealand continued to resist the Wehrmacht until 17 May, when Germany completed its occupation of the whole country.', 1940, 5, 14, 1940, 5, 15, 'day', '14 May 1940 – 15 May 1940', 71, 'https://en.wikipedia.org/wiki/German_invasion_of_the_Netherlands'),
  ('Q3532325', 'Battle of Rotterdam', 'The Battle of Rotterdam was a Second World War battle fought during the Battle of the Netherlands. Fought between 10 and 14 May 1940, it was a German attempt to seize the Dutch city.', 1940, 5, 10, 1940, 5, 14, 'day', '10 May 1940 – 14 May 1940', 51, 'https://en.wikipedia.org/wiki/Battle_of_Rotterdam'),
  ('Q387093', 'Battle of Arnhem', 'The Battle of Arnhem was fought during the Second World War, as part of the Allied Operation Market Garden. It took place around the Dutch city of Arnhem from 17 to 26 September 1944.', 1944, 9, 17, 1944, 9, 26, 'day', '17 September 1944 – 26 September 1944', 64, 'https://en.wikipedia.org/wiki/Battle_of_Arnhem'),
  ('Q697022', 'Battle of the Scheldt', 'The Battle of the Scheldt in World War II was a series of military operations to open up the Scheldt river between Antwerp and the North Sea for shipping, so that Antwerp''s port could be used to supply the Allies in north-west Europe. The operations were carried out by the First Canadian Army, with assistance from Polish and British units which had been attached.', 1944, 10, 2, 1944, 11, 8, 'day', '2 October 1944 – 8 November 1944', 65, 'https://en.wikipedia.org/wiki/Battle_of_the_Scheldt'),
  ('Q1332237', 'Battle of Overloon', 'The Battle of Overloon was fought in the Second World War between Allied forces and the German Army which took place in and around the village of Overloon in the south-east of the Netherlands between 30 September and 18 October 1944. The battle was an Allied victory, after the Allies launched Operation Aintree.', 1944, 9, 30, 1944, 10, 18, 'day', '30 September 1944 – 18 October 1944', 45, 'https://en.wikipedia.org/wiki/Battle_of_Overloon'),
  ('Q2562594', 'Hongerwinter', 'The Dutch famine of 1944–1945, also known as the Hunger Winter (from Dutch Hongerwinter), was a famine in the German-occupied Netherlands during World War II. The famine impacted the people in the densely populated and urbanized western provinces north of the great rivers during and after the harsh winter of 1944–1945. It began after the failure of Operation Market Garden, the Allied military offensive against the German occupiers of the Netherlands in September 1944.', 1944, 9, NULL, 1945, 4, NULL, 'month', 'September 1944 – April 1945', 57, 'https://en.wikipedia.org/wiki/Dutch_famine_of_1944%E2%80%931945'),
  ('Q6541032', 'Liberation of Arnhem', 'Operation Anger (sometimes mistakenly referred to as Operation Quick Anger) was a military operation to seize the city of Arnhem in April 1945, during the closing stages of the Second World War. It is also known as the Second Battle of Arnhem or the Liberation of Arnhem.', 1945, 4, 12, 1945, 4, 16, 'day', '12 April 1945 – 16 April 1945', 43, 'https://en.wikipedia.org/wiki/Liberation_of_Arnhem'),
  ('Q504934', 'North Sea flood of 1953', 'The North Sea flood of 1953, also known as the Big Flood or East Coast Flood (in England) or as the Flood Disaster (Dutch: Watersnoodramp), was a flood caused by a heavy storm surge in the North Sea that struck low-lying coastal areas of the Netherlands, Belgium, and the United Kingdom. More than 2,000 people were killed on land and hundreds more at sea.', 1953, 1, 31, 1953, 2, 1, 'day', '31 January 1953 – 1 February 1953', 67, 'https://en.wikipedia.org/wiki/North_Sea_flood_of_1953'),
  ('Q2186383', 'Bed-Ins For Peace', 'A bed-in is a nonviolent protest against wars, initiated by Yoko Ono and her husband John Lennon during a two week period in Amsterdam and Montreal as an experimental test of new ways to promote peace. As the Vietnam War raged in 1969, artists Ono and Lennon held one bed-in protest at the Hilton Hotel in Amsterdam and one at the Queen Elizabeth Hotel in Montreal.', 1969, NULL, NULL, 1969, 6, 1, 'year', '1969', 57, 'https://en.wikipedia.org/wiki/Bed-in'),
  ('Q2303215', 'NLM CityHopper Flight 431', 'NLM CityHopper Flight 431 was a flight by a Fokker F-28-4000, registration PH-CHI, that was operating an international scheduled Rotterdam–Eindhoven–Hamburg passenger service. On 6 October 1981, the aircraft encountered a tornado on the first leg, minutes after taking off from Rotterdam Airport, and crashed 15 miles (24 km) south-southeast of Rotterdam.', 1981, 10, 6, NULL, NULL, NULL, 'day', '6 October 1981', 47, 'https://en.wikipedia.org/wiki/NLM_CityHopper_Flight_431'),
  ('Q1323799', 'El Al Flight 1862', 'On 4 October 1992, El Al Flight 1862, a Boeing 747-200 cargo aircraft of the Israeli airline El Al, crashed into the Groeneveen and Klein-Kruitberg flats in the Bijlmermeer (colloquially "Bijlmer") neighbourhood of Amsterdam, the Netherlands. The accident is known in Dutch as the Bijlmerramp ("Bijlmer disaster").', 1992, 10, 4, NULL, NULL, NULL, 'day', '4 October 1992', 63, 'https://en.wikipedia.org/wiki/El_Al_Flight_1862'),
  ('Q2579458', 'KLM Cityhopper Flight 433', 'KLM Cityhopper Flight 433 was a Saab 340B, registered as PH-KSH, which crashed during an emergency landing on 4 April 1994, resulting in the death of 3 occupants, including the captain. Flight 433 was a routine scheduled flight from Amsterdam, the Netherlands, to Cardiff, Wales, United Kingdom.', 1994, 4, 4, NULL, NULL, NULL, 'day', '4 April 1994', 50, 'https://en.wikipedia.org/wiki/KLM_Cityhopper_Flight_433'),
  ('Q321961', 'Agreement on the Conservation of African-Eurasian Migratory Waterbirds', 'The Agreement on the Conservation of African-Eurasian Migratory Waterbirds, or African-Eurasian Waterbird Agreement (AEWA), is an independent international treaty developed under the auspices of the United Nations Environment Programme''s Convention on Migratory Species.', 1995, 6, 16, NULL, NULL, NULL, 'day', '16 June 1995', 62, 'https://en.wikipedia.org/wiki/Agreement_on_the_Conservation_of_African-Eurasian_Migratory_Waterbirds'),
  ('Q1384586', 'Enschede fireworks disaster', 'The Enschede fireworks disaster was a catastrophic fireworks explosion on 13 May 2000 in Enschede, Netherlands. The explosion killed 23 people, including four firefighters, and injured 950 others.', 2000, 5, 13, NULL, NULL, NULL, 'day', '13 May 2000', 55, 'https://en.wikipedia.org/wiki/Enschede_fireworks_disaster'),
  ('Q862548', 'Turkish Airlines Flight 1951', 'Turkish Airlines Flight 1951 (also known as the Poldercrash or the Schiphol Polderbaan incident) was a passenger flight that crashed during landing at Amsterdam Schiphol Airport, the Netherlands, on 25 February 2009, resulting in the deaths of nine passengers and crew, including all three pilots. The aircraft, a Turkish Airlines Boeing 737-800, crashed into a field about 1.5 km (0.9 mi) north of the Polderbaan runway (18R), prior to crossing the A9 motorway inbound, at 09:26 UTC (10:26 CET), having flown from Istanbul, Turkey.', 2009, 2, 25, NULL, NULL, NULL, 'day', '25 February 2009', 67, 'https://en.wikipedia.org/wiki/Turkish_Airlines_Flight_1951'),
  ('Q21117876', 'Dutch Ukraine–European Union Association Agreement referendum, 2016', 'An advisory referendum on the approval of the Ukraine–European Union Association Agreement was held in the Netherlands on 6 April 2016. The referendum question was: "Are you for or against the Approval Act of the Association Agreement between the European Union and Ukraine?" With a turnout of 32.28%, the threshold for a valid referendum was met.', 2016, 4, 6, NULL, NULL, NULL, 'day', '6 April 2016', 51, 'https://en.wikipedia.org/wiki/2016_Dutch_Ukraine%E2%80%93European_Union_Association_Agreement_referendum'),
  ('Q58805164', 'Yellow vests movement', 'The yellow vest movement (French: Mouvement des gilets jaunes, pronounced [muvmɑ̃ de ʒilɛ ʒon]) refers to those involved in a series of populist, grassroots weekly protests in France that began on 17 November 2018 and ended on 28 June 2020. After an online petition posted in May 2018 had attracted nearly one million signatures, mass demonstrations began on 17 November.', 2018, 11, 17, NULL, NULL, NULL, 'day', '17 November 2018', 80, 'https://en.wikipedia.org/wiki/Yellow_vests_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q107529288', '2021 European floods', 'In July 2021, several European countries were affected by severe floods. Some were catastrophic, causing deaths and widespread damage.', 2021, NULL, NULL, 2021, 7, 25, 'year', '2021', 73, 'https://en.wikipedia.org/wiki/2021_European_floods'),
  ('Q131045530', 'November 2024 Amsterdam attacks', 'On 6, 7 and 8 November 2024, before and after a UEFA Europa League football match in Amsterdam between Israeli club Maccabi Tel Aviv F.C. and Dutch club AFC Ajax, tensions over the Gaza war escalated to violence. Targets of the violence included an Arab taxi driver, Israeli Maccabi Tel Aviv fans, and pro-Palestinian protesters.', 2024, 11, 7, NULL, NULL, NULL, 'day', '7 November 2024', 58, 'https://en.wikipedia.org/wiki/November_2024_Amsterdam_riots'),
  ('Q137366682', '2025 Bulgarian protests', 'Protests began in Bulgaria on 26 November 2025 after the Zhelyazkov government announced a 2026 budget plan that would have increased taxes—specifically, the amounts individuals were to contribute to pension and social-security programs. The government suspended, then withdrew the budget, but demonstrations continued, with protestors demanding the resignation of the government and new elections.', 2025, 11, 26, NULL, NULL, NULL, 'day', '26 November 2025', 48, 'https://en.wikipedia.org/wiki/2025%E2%80%932026_Bulgarian_protests');
